import { parseArgs } from "node:util";
import {
  TuituiBotClient,
  type TuituiOutboundInteractiveMessage,
} from "@qihoo/tuitui-bot-sdk";
import { loadSampleConfig } from "./config.js";

function parseTo() {
  const { values } = parseArgs({
    options: {
      account: { type: "string" },
      uid: { type: "string" },
      group: { type: "string" },
    },
  });

  if (values.account && !values.uid && !values.group) {
    return client.to.account(values.account);
  }
  if (values.uid && !values.account && !values.group) {
    return client.to.uid(values.uid);
  }
  if (values.group && !values.account && !values.uid) {
    return client.to.group(values.group);
  }

  console.error(
    "用法: npm run sample:send-interactive -- --account <账号> | --uid <UID> | --group <群ID>",
  );
  process.exit(1);
}

const config = loadSampleConfig();
const client = new TuituiBotClient(config.appId, config.appSecret);
const interactive: TuituiOutboundInteractiveMessage = {
  head: { text: "交互消息示例" },
  body: { content: "请选择确认或取消" },
  action: [
    {
      text: "确认",
      name: "confirm",
      value: "confirm",
      color: "FFFFFF",
      bgcolor: "#3873FA",
    },
    {
      text: "取消",
      name: "cancel",
      value: "cancel",
      color: "FFFFFF",
      bgcolor: "#FA5151",
    },
  ],
};

try {
  const response = await client.im.sendInteractive({
    to: parseTo(),
    interactive,
  });

  console.log("交互消息发送成功", response);
} catch (error) {
  console.error("交互消息发送失败", error);
}
